import catalog from './growth-catalog.json';
import {
  GrowthReferenceChart,
  PatientGrowthResponse,
  GrowthObservation,
} from '../models/growth-chart.model';

/** Generated by backend cmd/growth-reference from pinned WHO sources; test-only. */
export const growthReferenceFixture = catalog as GrowthReferenceChart[];
export function patientGrowthFixture(
  patientId = 10492,
  withMeasurements = true,
): PatientGrowthResponse {
  const observations: GrowthObservation[] = withMeasurements
    ? [
        {
          source: 'BIRTH',
          encounterId: null,
          date: '2024-05-10',
          ageDays: 0,
          ageFormatted: 'Al nacer',
          weightKg: 3.35,
          heightCm: 50,
          headCircumferenceCm: 35,
          measurementMode: 'RECUMBENT',
        },
        {
          source: 'ENCOUNTER',
          encounterId: 1,
          date: '2026-09-15',
          ageDays: 858,
          ageFormatted: '2 años, 4 meses',
          weightKg: 11.4,
          heightCm: 86,
          headCircumferenceCm: 48,
          measurementMode: 'STANDING',
        },
      ]
    : [];
  return {
    patientId,
    birthDate: '2024-05-10',
    asOfDate: '2026-10-09',
    ageDays: 882,
    ageFormatted: '2 años, 4 meses',
    referenceSex: 'MALE',
    sexSource: 'SYSTEM_SEX',
    status: 'READY',
    observations,
    charts: growthReferenceFixture
      .filter((c) => c.definition.sex === 'MALE')
      .map((c) => ({
        ...c,
        applicable: [
          'wfa06_boys',
          'hfa06_boys',
          'hcfa06_boys',
          'wfh06_boys',
          'bfa06_boys',
        ].includes(c.definition.id),
        omitted: 0,
        points: observations
          .filter(
            (o) =>
              c.definition.reference === 'WHO 2006' &&
              (c.definition.ageMinMonths === 24
                ? o.ageDays >= 731
                : c.definition.ageMaxMonths === 24
                  ? o.ageDays <= 730
                  : true),
          )
          .map((o) => ({
            ...o,
            x: c.definition.x.variable === 'AGE' ? o.ageDays / 30.4375 : o.heightCm!,
            value:
              c.definition.y.variable === 'WEIGHT'
                ? o.weightKg!
                : c.definition.y.variable === 'HEAD_CIRCUMFERENCE'
                  ? o.headCircumferenceCm!
                  : c.definition.y.variable === 'BMI'
                    ? o.weightKg! / (o.heightCm! / 100) ** 2
                    : o.heightCm!,
            evaluation: { percentile: 50, zScore: 0 },
          })),
      })),
  };
}
